package services;
import java.util.*;import model.Medicine;import stringalgo.*;import dynamicprogramming.DamerauLevenshtein;import utils.InputUtil;
public class MedicineSearchService { public static void search(List<Medicine> meds,Scanner sc){String q=InputUtil.readLine(sc,"Enter medicine name: ");System.out.println("\nExact/substring matches:");boolean found=false;for(Medicine m:meds)if(KMP.search(m.getName(),q)>=0){System.out.println(m);found=true;}if(!found){int best=99;Medicine candidate=null;for(Medicine m:meds){int d=DamerauLevenshtein.distance(q,m.getName());if(d<best){best=d;candidate=m;}}if(candidate!=null&&best<=4)System.out.println("Did you mean: "+candidate.getName()+" (edit distance="+best+")");else System.out.println("No medicine found.");}System.out.println("Z algorithm check: "+(found?"matched":"no direct match")+" | Rabin-Karp index="+RabinKarp.search(String.join(" ",meds.stream().map(Medicine::getName).toList()),q));} }
